"use server";

// Generated by philote from page /books/new. Do not edit.
import { redirect } from "next/navigation";

import { books } from "@/lib/api";
import { type FormState, bool, failed, text } from "@/lib/form";
import type { Genre } from "@/lib/types";

export async function submit(_state: FormState, data: FormData): Promise<FormState> {
    const result = await books.create({
        title: text(data, "title"),
        genre: text<Genre>(data, "genre"),
        published: text(data, "published"),
        in_print: bool(data, "in_print"),
        author_id: text(data, "author_id"),
    });
    if (!result.ok) {
        return failed(data, result.error, result.issues);
    }
    redirect("/books");
}
